,"urgency":2,"priority":2,"type":1,"impact":2},"Telefonia - Problemas com Ramal":{"categoria_glpi":37,"urgency":2,"priority":2,"type":1,"impact":2},"Telefonia - Aparelho Telefonico":{"categoria_glpi":38,"urgency":2,"priority":2,"type":1,"impact":2},"Reparacao de Software":{"categoria_glpi":27,"urgency":2,"priority":2,"type":1,"impact":2}};

async function callRaw(method, url, headers) {
  const resp = await helpers.httpRequest({ method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true });
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed };
}

const r0 = await callRaw('GET', `${baseUrl}/initSession`, {
  'App-Token': appToken, 'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { erro: 'auth falhou' }}];
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token };

const forms = await callRaw('GET', `${baseUrl}/${I_FORM}?range=0-200`, H);
const formsArr = Array.isArray(forms.body) ? forms.body : (forms.body.data || []);
const formIdToInfo = {};
for (const f of formsArr) {
  if (f && f.is_deleted === 0 && MAPA[f.name]) {
    formIdToInfo[f.id] = { nome: f.name, ...MAPA[f.name] };
  }
}

const dests = await callRaw('GET', `${baseUrl}/${I_DEST}?range=0-500`, H);
const destsArr = Array.isArray(dests.body) ? dests.body : (dests.body.data || []);
const items = [];
for (const d of destsArr) {
  if (d && formIdToInfo[d.forms_forms_id]) {
    items.push({
      id: d.id,
      forms_forms_id: d.forms_forms_id,
      ...formIdToInfo[d.forms_forms_id]
    });
  }
}

await callRaw('GET', `${baseUrl}/killSession`, H);
return items.map(i => ({ json: i }));

const helpers = this.helpers;
const baseUrl = 'https://suporte.araraquara.sp.gov.br/api.php/v1';
const appToken = $('Carregar Tokens').first().json.app_token;
const userToken = $('Carregar Tokens').first().json.user_token;
const I_DEST = 'Glpi%5CForm%5CDestination%5CFormDestination';

async function callRaw(method, url, headers, body) {
  const opts = { method, url, headers, json: false, returnFullResponse: true, ignoreHttpStatusErrors: true };
  if (body !== undefined) opts.body = typeof body === 'string' ? body : JSON.stringify(body);
  const resp = await helpers.httpRequest(opts);
  let parsed = resp.body;
  if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch(_) {} }
  return { status: resp.statusCode || resp.status, body: parsed, bodyRaw: typeof resp.body === 'string' ? resp.body.substring(0,400) : '' };
}

const d = $input.first().json;

const r0 = await callRaw('GET', `${baseUrl}/initSession`, {
  'App-Token': appToken, 'Authorization': `user_token ${userToken}`
});
if (r0.status !== 200) return [{ json: { ...d, status: 'erro_auth' }}];
const H = { 'App-Token': appToken, 'Session-Token': r0.body.session_token, 'Content-Type': 'application/json' };

const cfg = {
  'glpi-form-destination-commonitilfield-titlefield': {
    value: `Solicitacao - ${d.nome}`
  },
  'glpi-form-destination-commonitilfield-contentfield_auto': true,
  'glpi-form-destination-commonitilfield-itilcategoryfield': {
    strategy: 'specific_value',
    specific_question_id: null,
    specific_itilcategories_id: d.categoria_glpi
  },
  'glpi-form-destination-commonitilfield-typefield': {
    strategy: 'specific_value',
    specific_question_id: null,
    specific_type: d.type
  },
  'glpi-form-destination-commonitilfield-urgencyfield': {
    strategy: 'specific_value',
    specific_question_id: null,
    specific_urgency: d.urgency
  },
  'glpi-form-destination-commonitilfield-impactfield': {
    strategy: 'specific_value',
    specific_question_id: null,
    specific_impact: d.impact
  },
  'glpi-form-destination-commonitilfield-priorityfield': {
    strategy: 'specific_value',
    specific_question_id: null,
    specific_priority: d.priority
  },
  'glpi-form-destination-commonitilfield-observerfield': {
    strategies: ['last_valid_answer'],
    specific_question_ids: [],
    specific_itilactors_ids: []
  },
  'glpi-form-destination-commonitilfield-requesttypefield': {
    strategy: 'specific_value',
    specific_question_id: null,
    specific_request_type: 1
  },
  'glpi-form-destination-commonitilfield-linkeditilobjectsfield': {
    strategy_configs: [{
      linktype: '', strategy: null, specific_itilobject: [],
      specific_question_ids: [], specific_destination_ids: []
    }]
  }
};

const body = {
  input: {
    id: d.id,
    name: `Chamado - ${d.nome}`,
    config: JSON.stringify(cfg)
  }
};

const r = await callRaw('PUT', `${baseUrl}/${I_DEST}/${d.id}`, H, body);
await callRaw('GET', `${baseUrl}/killSession`, H);

return [{ json: {
  ...d,
  status: r.status < 400 ? 'reconfigurado' : `falha_${r.status}`,
  erro: r.status >= 400 ? (r.bodyRaw || JSON.stringify(r.body)) : null
}}];

const items = $input.all().map(i => i.json);
const ok = items.filter(x => x.status === 'reconfigurado').length;
const fail = items.filter(x => x.status && x.status.startsWith('falha')).length;
return [{ json: {
  sucesso: fail === 0,
  total: items.length,
  reconfigurados: ok,
  falhas: fail,
  items
}}];

